import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';

const AnimatedGradientBackground = () => {
  const { theme } = useTheme();

  return (
    <motion.div
      className="fixed inset-0 z-0"
      animate={{
        background: [
          `linear-gradient(45deg, ${theme.primary}20, ${theme.secondary}20)`,
          `linear-gradient(90deg, ${theme.secondary}20, ${theme.primary}20)`,
          `linear-gradient(180deg, ${theme.primary}20, ${theme.secondary}20)`,
          `linear-gradient(270deg, ${theme.secondary}20, ${theme.primary}20)`,
        ],
      }}
      transition={{
        duration: 10,
        ease: "linear",
        repeat: Infinity,
      }}
    />
  );
};

export default AnimatedGradientBackground;
