import React, { useEffect } from 'react';
import { motion, useAnimation, useScroll, useTransform } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';
import AnimatedGradientBackground from '../components/AnimatedGradientBackground';
import { FaReact, FaNodeJs, FaPython, FaDatabase, FaDocker, FaAws } from 'react-icons/fa';
import { SiTypescript, SiGraphql } from 'react-icons/si';

const content = {
  EN: {
    title: "Technical Skills",
    skills: [
      { name: "React", icon: FaReact, level: 90 },
      { name: "Node.js", icon: FaNodeJs, level: 85 },
      { name: "TypeScript", icon: SiTypescript, level: 88 },
      { name: "Python", icon: FaPython, level: 80 },
      { name: "SQL", icon: FaDatabase, level: 75 },
      { name: "GraphQL", icon: SiGraphql, level: 70 },
      { name: "Docker", icon: FaDocker, level: 65 },
      { name: "AWS", icon: FaAws, level: 60 },
    ]
  },
  AR: {
    title: "المهارات التقنية",
    skills: [
      { name: "React", icon: FaReact, level: 90 },
      { name: "Node.js", icon: FaNodeJs, level: 85 },
      { name: "TypeScript", icon: SiTypescript, level: 88 },
      { name: "Python", icon: FaPython, level: 80 },
      { name: "SQL", icon: FaDatabase, level: 75 },
      { name: "GraphQL", icon: SiGraphql, level: 70 },
      { name: "Docker", icon: FaDocker, level: 65 },
      { name: "AWS", icon: FaAws, level: 60 },
    ]
  }
};

const SkillCard = ({ skill, theme, index }) => {
  return (
    <motion.div
      className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 flex flex-col items-center justify-center"
      style={{ 
        backgroundColor: theme.cardBg,
        border: `2px solid ${theme.primary}`,
      }}
      whileHover={{ scale: 1.05, rotate: 5 }}
      whileTap={{ scale: 0.95 }}
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.1 }}
    >
      <skill.icon size={48} style={{ color: theme.primary }} className="mb-4" />
      <h3 className="text-xl font-semibold mb-2" style={{ color: theme.primary }}>{skill.name}</h3>
      <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700 mt-2">
        <motion.div 
          className="h-2.5 rounded-full" 
          style={{ backgroundColor: theme.primary }}
          initial={{ width: 0 }}
          animate={{ width: `${skill.level}%` }}
          transition={{ duration: 1, delay: index * 0.1 }}
        />
      </div>
    </motion.div>
  );
};

const Skills = () => {
  const { theme, language } = useTheme();
  const currentContent = content[language];
  const isRTL = language === 'AR';
  
  const controls = useAnimation();
  const { scrollY } = useScroll();
  const y = useTransform(scrollY, [0, 300], [0, -50]);

  useEffect(() => {
    controls.start({ opacity: 1, y: 0 });
  }, [controls]);

  return (
    <section id="skills" className="min-h-screen py-20 relative overflow-hidden">
      <AnimatedGradientBackground />
      <div className="container mx-auto px-4 relative z-10">
        <motion.div
          className="max-w-4xl mx-auto"
          initial={{ opacity: 0, y: 50 }}
          animate={controls}
          style={{ y }}
        >
          <h2 className="text-4xl font-bold mb-12 text-center" style={{ color: theme.text }}>
            {currentContent.title}
          </h2>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-8">
            {currentContent.skills.map((skill, index) => (
              <SkillCard key={skill.name} skill={skill} theme={theme} index={index} />
            ))}
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Skills;

