import React, { useEffect, useState } from 'react';
import { motion, useAnimation, useScroll, useTransform } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';
import { FaGithub, FaLinkedin, FaEnvelope, FaWhatsapp } from 'react-icons/fa';
import emailjs from '@emailjs/browser';
import toast from 'react-hot-toast';
import AnimatedGradientBackground from '../components/AnimatedGradientBackground';

const content = {
  EN: {
    title: "Let's Create Something Amazing",
    subtitle: "Get in Touch",
    formLabels: {
      name: "Your Name",
      email: "Your Email",
      message: "Your Message",
      submit: "Send It My Way!"
    },
    toasts: {
      success: "Message sent successfully! I'll get back to you soon 🚀",
      error: "Oops! Something went wrong. Please try again 🛠️"
    }
  },
  AR: {
    title: "لنبتكر شيئًا مذهلاً",
    subtitle: "تواصل معي",
    formLabels: {
      name: "اسمك",
      email: "بريدك الإلكتروني",
      message: "رسالتك",
      submit: "أرسلها إلي!"
    },
    toasts: {
      success: "تم إرسال الرسالة بنجاح! سأرد عليك قريبًا 🚀",
      error: "عذرًا! حدث خطأ ما. يرجى المحاولة مرة أخرى 🛠️"
    }
  }
};

const DispersingText = ({ text, theme }) => {
  const characters = text.split('');
  
  return (
    <h1 className="text-4xl md:text-6xl font-bold mb-4 relative z-10">
      {characters.map((char, index) => (
        <motion.span
          key={index}
          style={{ color: theme.text, display: 'inline-block' }}
          animate={{
            y: [0, -20, 0],
            opacity: [1, 0.5, 1],
            scale: [1, 1.2, 1],
          }}
          transition={{
            duration: 3,
            ease: "easeInOut",
            repeat: Infinity,
            delay: index * 0.1,
          }}
        >
          {char}
        </motion.span>
      ))}
    </h1>
  );
};

const InputField = ({ label, id, type = "text", value, onChange, theme, rows }) => (
  <div className="mb-4">
    <label htmlFor={id} className="block text-sm font-medium mb-2" style={{ color: theme.text }}>
      {label}
    </label>
    {rows ? (
      <textarea
        id={id}
        rows={rows}
        className="w-full px-3 py-2 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
        style={{
          backgroundColor: `${theme.primary}15`,
          color: theme.text,
          borderColor: theme.primary,
        }}
        value={value}
        onChange={onChange}
        required
      />
    ) : (
      <input
        type={type}
        id={id}
        className="w-full px-3 py-2 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
        style={{
          backgroundColor: `${theme.primary}15`,
          color: theme.text,
          borderColor: theme.primary,
        }}
        value={value}
        onChange={onChange}
        required
      />
    )}
  </div>
);

const Contact = () => {
  const { theme, language } = useTheme();
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });
  
  const currentContent = content[language];
  const isRTL = language === 'AR';

  const controls = useAnimation();
  const { scrollY } = useScroll();
  const y = useTransform(scrollY, [0, 300], [0, -50]);

  useEffect(() => {
    controls.start({ opacity: 1, y: 0 });
  }, [controls]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    try {
      await emailjs.send(
        'YOUR_SERVICE_ID',
        'YOUR_TEMPLATE_ID',
        {
          from_name: formData.name,
          from_email: formData.email,
          message: formData.message,
          to_email: 'sebasalamah00@gmail.com',
        },
        'YOUR_PUBLIC_KEY'
      );
  
      setFormData({ name: '', email: '', message: '' });
      toast.success(currentContent.toasts.success);
    } catch (error) {
      toast.error(currentContent.toasts.error);
    } finally {
      setIsLoading(false);
    }
  };

  const socialLinks = [
    { icon: FaGithub, href: "https://github.com/Seba-00", label: "GitHub" },
    { icon: FaLinkedin, href: "https://linkedin.com/in/seba-salamah", label: "LinkedIn" },
    { icon: FaEnvelope, href: "mailto:sebasalamah00@gmail.com", label: "Email" },
    { icon: FaWhatsapp, href: "https://wa.me/966555948067", label: "WhatsApp" },
  ];

  return (
    <section id="contact" className={`min-h-screen py-20 relative overflow-hidden ${isRTL ? 'rtl' : 'ltr'}`}>
      <AnimatedGradientBackground />
      <div className="container mx-auto px-4 relative z-10">
        <motion.div
          className="max-w-4xl mx-auto"
          initial={{ opacity: 0, y: 50 }}
          animate={controls}
          style={{ y }}
        >
          <div className="text-center mb-12">
            <DispersingText text={currentContent.title} theme={theme} />
            <p className="text-xl" style={{ color: theme.textSecondary }}>{currentContent.subtitle}</p>
          </div>

          <div className="grid md:grid-cols-2 gap-8">
            <div>
              <h3 className="text-2xl font-bold mb-4" style={{ color: theme.primary }}>Let's Connect</h3>
              <div className="space-y-4">
                {socialLinks.map((link, index) => (
                  <motion.a
                    key={link.label}
                    href={link.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center space-x-3 group"
                    whileHover={{ x: 10 }}
                  >
                    <span className="w-10 h-10 rounded-full flex items-center justify-center transition-colors duration-300"
                          style={{ backgroundColor: `${theme.primary}20` }}>
                      <link.icon className="w-5 h-5" style={{ color: theme.primary }} />
                    </span>
                    <span className="text-lg transition-colors duration-300" style={{ color: theme.text }}>
                      {link.label}
                    </span>
                    </motion.a>
                  ))}
                </div>
              </div>
              <div>
                <h3 className="text-2xl font-bold mb-4" style={{ color: theme.primary }}>Send a Message</h3>
                <form onSubmit={handleSubmit} className="space-y-4">
                  <InputField
                    label={currentContent.formLabels.name}
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    theme={theme}
                  />
                  <InputField
                    label={currentContent.formLabels.email}
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                    theme={theme}
                  />
                  <InputField
                    label={currentContent.formLabels.message}
                    id="message"
                    value={formData.message}
                    onChange={(e) => setFormData({...formData, message: e.target.value})}
                    theme={theme}
                    rows={5}
                  />
                  <motion.button
                    type="submit"
                    disabled={isLoading}
                    className="w-full py-3 rounded-lg font-bold text-white transition-all duration-300"
                    style={{ backgroundColor: theme.primary }}
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    {isLoading ? (
                      <span className="flex items-center justify-center">
                        <motion.span
                          className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"
                          animate={{ rotate: 360 }}
                          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        />
                        <span className="ml-2">Sending...</span>
                      </span>
                    ) : (
                      currentContent.formLabels.submit
                    )}
                  </motion.button>
                </form>
              </div>
            </div>
          </motion.div>
        </div>
      </section>
    );
  };
  
  export default Contact;

